# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Timekeeping reservation writes: replay after a terminal state" do
  include_context "timekeeping entry writes"

  # Issue: "A replay after a terminal state changes nothing."
  it "changes no row or version when prepare, commit and abort are replayed after commit" do
    arrange = timekeeping_arrange
    company = arrange.company
    service = arrange.service_identity(company:, name: "invoice-boundary",
                                       operations: %w[prepare commit abort mark_billed detach_entries])
    user = arrange.user(company:, role: "employee")
    entry = arrange.entry(company:, user:, project: arrange.project(company:))
    operation_id = SecureRandom.uuid
    headers = { "Authorization" => "Bearer #{service}", "Content-Type" => "application/json" }
    send_command = lambda do |route, body|
      post("/v1/companies/#{company}/reservations/#{route}",
           params: body.merge("invoice_id" => 501, "operation_id" => operation_id,
                              "generation" => arrange.current_generation).to_json, headers:)
      response
    end
    prepare_body = { "disposition" => "active", "entries" => [entry] }

    expect(send_command.call("prepare", prepare_body).status).to eq(200)
    first_commit = send_command.call("commit", {})
    expect(first_commit.status).to eq(200)
    first_commit_body = JSON.parse(first_commit.body)
    counts = [Reservation.count, AuditEvent.count, OutboxSnapshot.count, Entry.sum(:version),
              Reservation.where(state: "committed").count]

    prepare_replay = send_command.call("prepare", prepare_body)
    expect(JSON.parse(prepare_replay.body).fetch("state")).to eq("committed")
    expect(JSON.parse(send_command.call("abort", {}).body)).to eq("dropped" => 0)
    expect(JSON.parse(send_command.call("commit", {}).body)).to eq(first_commit_body)

    expect([Reservation.count, AuditEvent.count, OutboxSnapshot.count, Entry.sum(:version),
            Reservation.where(state: "committed").count]).to eq(counts)
  end
end

RSpec.describe "Timekeeping reservation writes: operation ids across companies" do
  include_context "timekeeping entry writes"

  # Issue: "Operation ids are unique only within a company."
  # Acceptance: "another company's operation id never matches".
  it "never commits or aborts another company's operation that uses the same operation id and invoice id" do
    arrange = timekeeping_arrange
    company = arrange.company
    other_company = arrange.company
    routes = %w[prepare commit abort mark_billed detach_entries]
    service = arrange.service_identity(company:, name: "invoice-boundary", operations: routes)
    other_service = arrange.service_identity(company: other_company, name: "invoice-boundary", operations: routes)
    entry = arrange.entry(company:, user: arrange.user(company:, role: "employee"), project: arrange.project(company:))
    operation_id = SecureRandom.uuid
    command = lambda do |path_company, credential, route, extra = {}|
      post "/v1/companies/#{path_company}/reservations/#{route}",
           params: { "invoice_id" => 501, "operation_id" => operation_id,
                     "generation" => arrange.current_generation }.merge(extra).to_json,
           headers: { "Authorization" => "Bearer #{credential}", "Content-Type" => "application/json" }
      response
    end

    expect(command.call(company, service, "prepare", "disposition" => "active", "entries" => [entry]).status).to eq(200)

    foreign_abort = command.call(other_company, other_service, "abort")
    foreign_commit = command.call(other_company, other_service, "commit")

    expect([foreign_abort.status, foreign_commit.status]).to eq([404, 404])
    expect(Reservation.where(entry_id: entry).pluck(:invoice_id, :state)).to eq([[501, "provisional"]])
    expect(JSON.parse(command.call(company, service, "commit").body)).to eq("reserved" => 1, "released" => 0)
  end
end

RSpec.describe "Timekeeping reservation writes: a refused prepare leaves nothing behind" do
  include_context "timekeeping entry writes"

  # Acceptance: "Prepare refuses an entry another kept invoice holds with
  # on_another_invoice, and one conflict reserves nothing". A refused prepare
  # that left its operation behind would turn the retry into a replay or an
  # unresolved_operation refusal.
  it "lets a refused prepare be retried with the same operation id once the conflicting entry is removed" do
    arrange = timekeeping_arrange
    company = arrange.company
    service = arrange.service_identity(company:, name: "invoice-boundary",
                                       operations: %w[prepare commit abort mark_billed detach_entries])
    user = arrange.user(company:, role: "employee")
    project = arrange.project(company:)
    free_a = arrange.entry(company:, user:, project:)
    free_b = arrange.entry(company:, user:, project:)
    held = arrange.reserved_entry(company:, invoice_id: 777, state: "committed")
    operation_id = SecureRandom.uuid
    prepare = lambda do |entries|
      post "/v1/companies/#{company}/reservations/prepare",
           params: { "invoice_id" => 501, "operation_id" => operation_id, "generation" => arrange.current_generation,
                     "disposition" => "active", "entries" => entries }.to_json,
           headers: { "Authorization" => "Bearer #{service}", "Content-Type" => "application/json" }
      response
    end
    counts = [Reservation.count, AuditEvent.count, OutboxSnapshot.count, Entry.sum(:version)]

    refused = prepare.call([free_a, held, free_b])

    expect(refused.status).to eq(409)
    expect(JSON.parse(refused.body)).to eq(
      "reason" => "conflict", "conflicts" => [{ "entry_id" => held, "reason" => "on_another_invoice" }]
    )
    expect([Reservation.count, AuditEvent.count, OutboxSnapshot.count, Entry.sum(:version)]).to eq(counts)

    retried = prepare.call([free_a, free_b])

    expect(retried.status).to eq(200)
    expect(JSON.parse(retried.body).fetch("state")).to eq("prepared")
    expect(Reservation.where(entry_id: [free_a, free_b], invoice_id: 501, state: "provisional").count).to eq(2)
    expect(Reservation.where(entry_id: held).pluck(:invoice_id, :state)).to eq([[777, "committed"]])
  end
end
